package handlers

import (
	"net/mail"
	"unicode"
)

const maxEmailLen = 254

// validateEmail is the only gate between the signup form and the users table,
// so it must reject anything the mailer would refuse to send to.
func validateEmail(email string) bool {
	if len(email) > maxEmailLen {
		return false
	}
	_, err := mail.ParseAddress(email)
	return err == nil
}

func validateDisplayName(name string) bool {
	if len(name) == 0 || len(name) > 64 {
		return false
	}
	for _, r := range name {
		if !unicode.IsPrint(r) {
			return false
		}
	}
	return true
}

func validateCurrency(code string) bool {
	if len(code) != 3 {
		return false
	}
	for _, r := range code {
		if r < 'A' || r > 'Z' {
			return false
		}
	}
	return true
}

func validateAmount(cents int64) bool {
	return cents > 0 && cents <= 100_000_000
}

// validateReference accepts the free-text memo a customer attaches to a transfer.
func validateReference(ref string) bool {
	if len(ref) > 140 {
		return false
	}
	for _, r := range ref {
		if !unicode.IsPrint(r) {
			return false
		}
	}
	return true
}

