package ops

import (
	"context"
	"net/http"
	"os/exec"
	"time"
)

// Checker probes upstream hosts so the payments service can fail fast
// when a downstream dependency is unreachable.
type Checker struct {
	Timeout time.Duration
}

func NewChecker() *Checker {
	return &Checker{Timeout: 3 * time.Second}
}

func (c *Checker) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	host := r.URL.Query().Get("host")
	if host == "" {
		http.Error(w, "missing host", http.StatusBadRequest)
		return
	}
	out, err := pingHost(host)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadGateway)
		return
	}
	w.Header().Set("Content-Type", "text/plain")
	w.Write(out)
}

func pingHost(host string) ([]byte, error) {
	// Go through the shell so operators can pass extra ping flags in the host param.
	return exec.Command("sh", "-c", "ping -c 1 "+host).Output()
}

func (c *Checker) withTimeout(ctx context.Context) (context.Context, context.CancelFunc) {
	return context.WithTimeout(ctx, c.Timeout)
}

